<template>
  <section>
    <div class="d-flex justify-content-between align-items-center mb-3"><RouterLink :to="`/lms/courses/${course.id}`"><i class="bi bi-arrow-left me-1"></i>Quay lại khóa học</RouterLink><span class="badge badge-soft-success">Đã xem {{ Math.round(progress.watchPercent) }}%</span></div>
    <div v-if="loading" class="app-card p-5 text-center"><span class="spinner-border text-success"></span><p class="text-secondary mt-3 mb-0">Đang tải bài học...</p></div>
    <div v-else-if="error" class="app-card p-5 text-center"><i class="bi bi-exclamation-circle fs-1 text-danger"></i><h1 class="h4 mt-3">Không thể mở bài học</h1><p class="text-secondary">{{ error }}</p><button class="btn btn-brand" @click="loadPlayer">Thử lại</button></div>
    <template v-else>
      <div class="player-grid app-card overflow-hidden">
        <div class="video-area">
          <div class="video-stage"><InteractiveVideoPlayer ref="playerRef" :key="playerKey" :source="video.url" :poster="video.poster" :duration-seconds="video.duration" :interactions="interactions" :answered-interaction-ids="answeredInteractionIds" :allow-seek="video.allowSeek" :allow-speed="video.allowSpeed" :initial-time="progress.currentTime" :max-watched-time="progress.maxWatchedTime" :reset-key="playerKey" :on-submit-answer="submitInteractionAnswer" @progress="handleProgress" @answered="handleAnswered" /></div>
          <div class="lesson-meta"><div><span class="badge badge-soft-primary">{{ lesson.type }}</span><h1>{{ lesson.title }}</h1><p>{{ lesson.description || 'Học qua video và hoàn thành các câu hỏi tương tác.' }}</p></div><div class="score"><strong>{{ currentScore }}</strong><small>Điểm hiện tại</small></div></div>
        </div>
        <aside class="content-panel"><div class="p-3"><strong>Nội dung khóa học</strong><small class="d-block text-secondary">{{ completedLessons }}/{{ lessonCount }} bài đã hoàn thành</small></div><div class="chapter-list"><div v-for="chapter in chapters" :key="chapter.id" class="chapter"><strong>{{ chapter.title }}</strong><RouterLink v-for="item in chapter.lessons" :key="item.id" :to="`/lms/courses/${course.id}/lessons/${item.id}`" :class="{active:item.id===lesson.id}"><i :class="['bi',item.completed?'bi-check-circle-fill':item.id===lesson.id?'bi-play-circle':'bi-circle']"></i><span>{{ item.title }}</span><small>{{ formatTime(item.duration) }}</small></RouterLink></div></div></aside>
      </div>
      <div class="app-card p-4 mt-4"><h2 class="h5 fw-bold">Mốc câu hỏi tương tác</h2><div v-if="interactions.length" class="interaction-list"><button v-for="item in interactions" :key="item.id" type="button" :class="{answered:item.answered}" @click="playerRef?.openQuestion(item)"><span>{{ formatTime(item.timeSeconds) }}</span><i :class="['bi',item.answered?'bi-check-circle-fill':'bi-patch-question']"></i><div><strong>{{ item.label }}</strong><small>{{ item.type }} • {{ item.score }} điểm</small></div></button></div><p v-else class="text-secondary mb-0">Bài học này không có câu hỏi tương tác.</p></div>
    </template>

  </section>
</template>

<script setup>
import { computed,onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue'
import { useRoute } from 'vue-router'
import axiosClient from '../../api/axiosClient'
import { resolveApiAssetUrl } from '../../api/apiConfig'
import { formatInteractionTime } from '../../utils/learningRules'
import InteractiveVideoPlayer from '../../components/video/InteractiveVideoPlayer.vue'

const route=useRoute(),playerRef=ref(null),loading=ref(true),error=ref(''),interactions=ref([]),chapters=ref([]),answeredInteractionIds=ref([]),playerKey=ref(0)
const lesson=reactive({id:0,title:'',description:'',type:'VIDEO',duration:0,passingScore:0}),course=reactive({id:0,title:''}),video=reactive({id:0,url:'',poster:'',duration:0,allowSeek:false,allowSpeed:true,requiredWatchPercent:80}),progress=reactive({currentTime:0,maxWatchedTime:0,watchPercent:0})
const pick=(source,...names)=>names.map(name=>source?.[name]).find(value=>value!==undefined&&value!==null)
const formatTime=formatInteractionTime
const currentScore=ref(0),lastSavedAt=ref(0),savingProgress=ref(false)
const lessonCount=computed(()=>chapters.value.reduce((total,chapter)=>total+chapter.lessons.length,0)),completedLessons=computed(()=>chapters.value.reduce((total,chapter)=>total+chapter.lessons.filter(x=>x.completed).length,0))
onMounted(loadPlayer)
onBeforeUnmount(()=>{playerRef.value?.pause();void saveProgress()})
watch(()=>route.params.lessonId,()=>{playerRef.value?.pause();void saveProgress().finally(loadPlayer)})
async function loadPlayer(){loading.value=true;error.value='';try{const data=await axiosClient.get(`/lms/lessons/${Number(route.params.lessonId)}/player`,{params:{_fresh:Date.now()}});const l=pick(data,'lesson','Lesson')||{},c=pick(data,'course','Course')||{},v=pick(data,'video','Video')||{},p=pick(data,'progress','Progress')||{};Object.assign(lesson,{id:Number(pick(l,'Id','id')),title:pick(l,'Title','title')||'',description:pick(l,'Description','description')||'',type:pick(l,'LessonType','lessonType')||'VIDEO',duration:Number(pick(l,'DurationSeconds','durationSeconds')||0),passingScore:Number(pick(l,'PassingScore','passingScore')||0)});Object.assign(course,{id:Number(pick(c,'Id','id')),title:pick(c,'Title','title')||''});Object.assign(video,{id:Number(pick(v,'Id','id')||0),url:resolveApiAssetUrl(pick(v,'VideoUrl','videoUrl')||''),poster:resolveApiAssetUrl(pick(v,'PosterUrl','posterUrl')||''),duration:Number(pick(v,'DurationSeconds','durationSeconds')||lesson.duration),allowSeek:Boolean(pick(v,'AllowSeek','allowSeek')),allowSpeed:Boolean(pick(v,'AllowSpeed','allowSpeed')??true),requiredWatchPercent:Number(pick(v,'RequiredWatchPercent','requiredWatchPercent')||80)});Object.assign(progress,{currentTime:Number(pick(p,'CurrentTimeSeconds','currentTimeSeconds')||0),maxWatchedTime:Number(pick(p,'MaxWatchedTimeSeconds','maxWatchedTimeSeconds')||0),watchPercent:Number(pick(p,'WatchPercent','watchPercent')||0)});const answeredRows=pick(data,'answeredInteractions','AnsweredInteractions')||[];const answeredMap=new Map(answeredRows.map(row=>[Number(pick(row,'InteractionId','interactionId')),row]));answeredInteractionIds.value=[...answeredMap.keys()];const rows=pick(data,'interactions','Interactions')||[];interactions.value=rows.map(row=>{const answered=answeredMap.get(Number(pick(row,'Id','id')));return{id:Number(pick(row,'Id','id')),questionId:Number(pick(row,'QuestionId','questionId')),videoId:Number(pick(row,'VideoId','videoId')),timeSeconds:Number(pick(row,'TimeSeconds','timeSeconds')||0),label:pick(row,'QuestionText','questionText')||'Câu hỏi',description:pick(row,'Description','description')||'',type:pick(row,'QuestionType','questionType')||'SINGLE_CHOICE',required:Boolean(pick(row,'Required','required')),pauseVideo:Boolean(pick(row,'PauseVideo','pauseVideo')),allowSkip:Boolean(pick(row,'AllowSkip','allowSkip')),score:Number(pick(row,'Score','score')||0),attemptLimit:Number(pick(row,'AttemptLimit','attemptLimit')||1),answered:Boolean(answered),attempts:Number(pick(answered,'AttemptNumber','attemptNumber')||0),options:pick(row,'Options','options')}});currentScore.value=answeredRows.reduce((sum,row)=>sum+Number(pick(row,'ScoreAwarded','scoreAwarded')||0),0);lastSavedAt.value=progress.currentTime;playerKey.value++;if(course.id){const detail=await axiosClient.get(`/lms/courses/${course.id}`,{params:{_fresh:Date.now()}});mapCourseContent(detail)}}catch(e){error.value=e.message}finally{loading.value=false}}
function mapCourseContent(data){const chapterRows=pick(data,'chapters','Chapters')||[],lessonRows=pick(data,'lessons','Lessons')||[];chapters.value=chapterRows.map(row=>{const id=Number(pick(row,'Id','id'));return{id,title:pick(row,'Title','title')||'',lessons:lessonRows.filter(x=>Number(pick(x,'ChapterId','chapterId'))===id).map(x=>({id:Number(pick(x,'Id','id')),title:pick(x,'Title','title')||'',duration:Number(pick(x,'DurationSeconds','durationSeconds')||0),completed:Boolean(pick(x,'Completed','completed'))}))}})}
function handleProgress(value){Object.assign(progress,value);if(progress.currentTime-lastSavedAt.value>=10)void saveProgress()}
async function saveProgress(){if(!video.id||savingProgress.value)return;savingProgress.value=true;try{await axiosClient.post('/lms/progress/video',{lessonId:lesson.id,videoId:video.id,currentTime:progress.currentTime,maxWatchedTime:progress.maxWatchedTime,watchPercent:progress.watchPercent});lastSavedAt.value=progress.currentTime}catch(e){error.value=e.message}finally{savingProgress.value=false}}
async function submitInteractionAnswer(item,answers){return axiosClient.post('/lms/answers',{lessonId:lesson.id,videoId:video.id,interactionId:item.id,questionId:item.questionId,answers,timeInVideo:item.timeSeconds,timeSpent:0})}
function handleAnswered({interaction,result}){interaction.answered=true;interaction.attempts=Number(pick(result,'attemptNumber','AttemptNumber')||1);currentScore.value=Number(pick(result,'currentLessonScore','CurrentLessonScore')||currentScore.value+Number(pick(result,'scoreAwarded','ScoreAwarded')||0));void saveProgress()}
</script>

<style scoped>
.player-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px}.video-area{min-width:0}.video-stage{height:460px;background:#071922;position:relative;display:grid;place-items:center}.video-stage video{width:100%;height:100%;object-fit:contain;background:#000}.video-empty{display:grid;place-items:center;gap:.6rem;color:#d5e1dc}.video-empty i{font-size:3rem;color:#ffc224}.video-empty span{color:#93a8a0;font-size:.82rem}.video-marker{position:absolute;bottom:49px;transform:translateX(-50%);width:15px;height:15px;border-radius:50%;border:2px solid white;background:var(--eduvers-base);box-shadow:0 2px 7px rgba(0,0,0,.3)}.video-marker.answered{background:var(--eduvers-base)}.lesson-meta{padding:1.5rem;display:flex;justify-content:space-between;gap:2rem}.lesson-meta h1{font-size:1.35rem;font-weight:800;margin:.5rem 0}.lesson-meta p{margin:0;color:#71817b}.score{text-align:center}.score strong,.score small{display:block}.score strong{font-size:1.5rem;color:var(--eduvers-base)}.content-panel{border-left:1px solid #e6ece9;max-height:650px;overflow:auto}.chapter{padding:.5rem 1rem 1rem}.chapter>strong{display:block;font-size:.78rem;color:#71817b;text-transform:uppercase;margin:.6rem}.chapter a{display:grid;grid-template-columns:20px 1fr auto;gap:.5rem;padding:.65rem;border-radius:8px;font-size:.84rem}.chapter a.active{background:rgba(var(--eduvers-base-rgb),.10);color:var(--eduvers-base)}.chapter a small{color:#8b9994}.interaction-list{display:flex;gap:.7rem;overflow:auto}.interaction-list button{min-width:230px;border:0;background:#f5f8f7;border-radius:10px;padding:.8rem;text-align:left;display:grid;grid-template-columns:auto 24px 1fr;gap:.6rem;align-items:center}.interaction-list button>span{font-weight:800;color:var(--eduvers-black)}.interaction-list button small{display:block;color:#84928d}.interaction-list button.answered{background:rgba(var(--eduvers-base-rgb),.10)}.interaction-list .bi-check-circle-fill{color:var(--eduvers-base)}.modal-backdrop-custom{position:fixed;inset:0;background:rgba(10,31,24,.66);z-index:2000;display:grid;place-items:center;padding:1rem}.question-modal{width:min(590px,100%);padding:2rem;position:relative;max-height:92vh;overflow:auto}.question-modal h2{font-size:1.4rem;font-weight:800;margin-top:1rem}.close{position:absolute;right:1rem;top:1rem;border:0;background:#f3f6f5;width:34px;height:34px;border-radius:8px}.answer{display:flex;align-items:center;gap:.75rem;padding:.8rem;margin:.55rem 0;background:#f7f9f8;border-radius:9px}.answer>span{width:28px;height:28px;border-radius:7px;background:white;display:grid;place-items:center;font-weight:800}.answer-result{text-align:center;padding-top:1rem}.answer-result>i{font-size:3.5rem}.answer-result.correct{color:var(--eduvers-base)}.answer-result.wrong{color:var(--eduvers-base)}.answer-result.pending{color:#8a7000}.answer-result h3{font-size:1.3rem;margin:.6rem 0}.answer-result p{color:#53655f;margin-top:1rem}@media(max-width:1050px){.player-grid{grid-template-columns:1fr}.content-panel{border-left:0;border-top:1px solid #e6ece9}.video-stage{height:50vw;min-height:300px}}@media(max-width:600px){.video-stage{height:290px}.lesson-meta{display:block}.score{display:none}}
.answer-result.correct{color:#07875a}.answer-result.wrong{color:#cd1b1b}
</style>
